  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Jaca – citadela', 'Pěticípá renesanční pevnost ze 16. století, jedna z nejzachovalejších v Evropě — v příkopu se navíc prohánějí jeleni. Jaca je přirozená brána do aragonských Pyrenejí a dobré místo na kávu před horami.', 42.5710, -0.5498, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ciudadela%20Jaca%20Vista%20Aerea.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ciudadela%20Jaca%20Vista%20Aerea.JPG"}'::text[], 0),
    (v_route, 'Biescas', 'Kamenné městečko na řece Gállego u vstupu do údolí Tena. Ideální rychlá zastávka před stoupáním do průsmyku Cotefablo.', 42.6273, -0.3192, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20des%20del%20Canal%20de%20Arbenuso.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20des%20del%20Canal%20de%20Arbenuso.jpg"}'::text[], 1),
    (v_route, 'Torla a údolí Ordesa', 'Vesnice s břidlicovými střechami pod kolmou stěnou Mondarruega, brána národního parku Ordesa y Monte Perdido. Z vyhlídek nad vsí se otevírá jeden z nejslavnějších horských pohledů Španělska.', 42.6273, -0.1125, 'https://commons.wikimedia.org/wiki/Special:FilePath/Torla,%20valle%20ordesa.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Torla,%20valle%20ordesa.jpg"}'::text[], 2),
    (v_route, 'Aínsa – Plaza Mayor', 'Dokonale dochované středověké náměstí s podloubím a románskou zvonicí, od níž je vidět masiv Monte Perdido. Jedno z nejkrásnějších městeček Španělska.', 42.4162, 0.1381, 'https://commons.wikimedia.org/wiki/Special:FilePath/Plaza%20Mayor,%20Ainsa,%20Spain.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Plaza%20Mayor,%20Ainsa,%20Spain.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Callizo (Aínsa)', 'Oceňovaná kuchyně přímo na středověkém náměstí — moderní pojetí horských surovin Pyrenejí. V sezóně rezervuj předem, degustační menu stojí za delší pauzu.', 42.4165, 0.1379, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20de%20A%C3%ADnsa.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20de%20A%C3%ADnsa.jpg"}'::text[], 4),
    (v_route, 'Bielsa a Valle de Pineta', 'Slepé ledovcové údolí zakončené kilometrovou stěnou Monte Perdido. Silnička z Bielsy k parádoru na konci údolí je nádherná tečka za trasou.', 42.6335, 0.2213, 'https://commons.wikimedia.org/wiki/Special:FilePath/Valle%20de%20Pineta%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Valle%20de%20Pineta%2001.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'San Sebastián – pláž La Concha', 'Mušlová zátoka s promenádou patří k nejkrásnějším městským plážím světa. Elegantní lázeňské město je zároveň hlavním městem baskické gastronomie.', 43.3183, -1.9860, 'https://commons.wikimedia.org/wiki/Special:FilePath/LA%20CONCHA,%20SAN%20SEBASTI%C3%81N,%20SPAIN.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/LA%20CONCHA,%20SAN%20SEBASTI%C3%81N,%20SPAIN.JPG"}'::text[], 0),
    (v_route, 'Getaria – rybářský přístav', 'Rodiště mořeplavce Elcana s přístavem schovaným za skalnatou horou San Antón, které místní říkají Myš. Nad grily u přístavu voní čerstvě ulovené ryby.', 43.3059, -2.2039, 'https://commons.wikimedia.org/wiki/Special:FilePath/Getaria,%20Harbour%20and%20Mount%20San%20Anton.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Getaria,%20Harbour%20and%20Mount%20San%20Anton.jpg"}'::text[], 1),
    (v_route, 'Restaurace: Elkano (Getaria)', 'Legendární podnik s michelinskou hvězdou, kde se celé ryby grilují na dřevěném uhlí před vchodem. Jedna z nejslavnějších rybích restaurací Evropy — rezervace nutná.', 43.3055, -2.2045, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20de%20Getaria.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20de%20Getaria.jpg"}'::text[], 2),
    (v_route, 'Zumaia – útesy flysch', 'Vrstevnaté útesy jako listy kamenné knihy staré 60 milionů let, známé i ze Hry o trůny. Nejlepší pohled je z pláže Itzurun pod kostelem San Telmo.', 43.2989, -2.2616, 'https://commons.wikimedia.org/wiki/Special:FilePath/Zumaia%27s%20Flysch%20cliffs..JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Zumaia%27s%20Flysch%20cliffs..JPG"}'::text[], 3),
    (v_route, 'Lekeitio', 'Barevný rybářský přístav s ostrůvkem, na který se dá při odlivu dojít pěšky po dně. Skvělé místo na kávu nad mořem v půlce trasy.', 43.3645, -2.5039, 'https://commons.wikimedia.org/wiki/Special:FilePath/Puerto%20de%20Lekeitio%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Puerto%20de%20Lekeitio%20-%20panoramio.jpg"}'::text[], 4),
    (v_route, 'Gernika', 'Posvátné město Basků s dubem, pod nímž se po staletí scházel baskický sněm; bombardování z roku 1937 zvěčnil Picasso. Krátká zastávka s velkou historií.', 43.3170, -2.6716, 'https://commons.wikimedia.org/wiki/Special:FilePath/Arbol%20de%20Gernika%20d%C3%ADa.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Arbol%20de%20Gernika%20d%C3%ADa.jpg"}'::text[], 5),
    (v_route, 'San Juan de Gaztelugatxe', 'Poustevna na skalnatém ostrůvku spojená s pevninou kamenným mostem a 241 schody — Dračí kámen ze Hry o trůny. Nejikoničtější místo baskického pobřeží.', 43.4470, -2.7854, 'https://commons.wikimedia.org/wiki/Special:FilePath/San%20Juan%20de%20Gaztelugatxe,%20Bermeo.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/San%20Juan%20de%20Gaztelugatxe,%20Bermeo.JPG"}'::text[], 6),
    (v_route, 'Bilbao – Guggenheimovo muzeum', 'Titanová vlna Franka Gehryho, která proměnila průmyslové město v metropoli moderního umění. Zaparkuj na nábřeží a projdi se kolem obřího pavouka Maman.', 43.2687, -2.9340, 'https://commons.wikimedia.org/wiki/Special:FilePath/Guggenheim%20Museum,%20Bilbao,%20July%202010%20(11).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Guggenheim%20Museum,%20Bilbao,%20July%202010%20(11).JPG"}'::text[], 7);
  insert into public.routes
