  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Santiago de Compostela – katedrála', 'Cíl svatojakubských poutí s barokním průčelím Obradoiro. Na náměstí sleduj poutníky, kteří právě došli — za chvíli pojedeš tam, kam mnozí pokračují: na konec světa.', 42.8806, -8.5449, 'https://commons.wikimedia.org/wiki/Special:FilePath/Obradoiro%20facade%20-%20Cathedral%20of%20Santiago%20de%20Compostela%20(5).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Obradoiro%20facade%20-%20Cathedral%20of%20Santiago%20de%20Compostela%20(5).JPG"}'::text[], 0),
    (v_route, 'Ponte Maceira', 'Středověký most přes řeku Tambre v jedné z nejmalebnějších vesnic Galicie. Kamenné mlýny, jezy a zeleň jako z pohlednice.', 42.9070, -8.7080, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ponte%20Maceira.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ponte%20Maceira.jpg"}'::text[], 1),
    (v_route, 'Vodopád Ézaro', 'Jediné místo v Evropě, kde řeka padá po žulových deskách přímo do oceánu. Hora Pindo nad vodopádem bývala posvátným Olympem Keltů.', 42.9110, -9.1280, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ezaro%20-%2003%20-%20Fervenza-Cascada-Waterfall.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ezaro%20-%2003%20-%20Fervenza-Cascada-Waterfall.jpg"}'::text[], 2),
    (v_route, 'Fisterra – maják na konci světa', 'Mys, který Římané považovali za konec známého světa a kde poutníci tradičně pálili boty. Nultý kilometrovník a nekonečný Atlantik pod útesy.', 42.8830, -9.2720, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cape%20Finisterre%20-%20lighthouse.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cape%20Finisterre%20-%20lighthouse.jpg"}'::text[], 3),
    (v_route, 'Restaurace: O Semáforo (Fisterra)', 'Restaurace v bývalé signální stanici přímo na mysu — čerstvé mořské plody s výhledem, který nemá v Evropě obdoby.', 42.8827, -9.2716, 'https://commons.wikimedia.org/wiki/Special:FilePath/Faro%20de%20Fisterra.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Faro%20de%20Fisterra.jpg"}'::text[], 4),
    (v_route, 'Muxía – svatyně Virxe da Barca', 'Poutní kostel na skalách bičovaných příbojem; podle legendy sem Panna Maria připlula na kamenné lodi. Divoké zakončení Costa da Morte.', 43.1120, -9.2180, 'https://commons.wikimedia.org/wiki/Special:FilePath/Santuario%20de%20Nuestra%20Se%C3%B1ora%20de%20La%20Barca.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Santuario%20de%20Nuestra%20Se%C3%B1ora%20de%20La%20Barca.JPG"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Cáceres – staré město', 'Kompletně dochované středověké a renesanční město na seznamu UNESCO; věže paláců obsadili čápi. Sloužilo i jako kulisa Hry o trůny.', 39.4753, -6.3723, 'https://commons.wikimedia.org/wiki/Special:FilePath/Plaza%20de%20Santa%20Mar%C3%ADa,%20C%C3%A1ceres.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Plaza%20de%20Santa%20Mar%C3%ADa,%20C%C3%A1ceres.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/C%C3%A1ceres,%20Ciudad%20Monumental.JPG"}'::text[], 0),
    (v_route, 'Trujillo – Plaza Mayor', 'Rodiště dobyvatele Peru Francisca Pizarra s jedním z nejkrásnějších náměstí Španělska a jeho jezdeckou sochou. Nad městem stojí maurský hrad s výhledem na dehesu.', 39.4633, -5.8810, 'https://commons.wikimedia.org/wiki/Special:FilePath/Plaza%20Mayor%20con%20la%20estatua%20ecuestre%20de%20Francisco%20Pizarro.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Plaza%20Mayor%20con%20la%20estatua%20ecuestre%20de%20Francisco%20Pizarro.jpg"}'::text[], 1),
    (v_route, 'Restaurace: La Troya (Trujillo)', 'Legendární mesón přímo na náměstí — obří porce extremadurské kuchyně, ibérico vepřové a proslulý předkrm zdarma. Instituce, kam se jezdí přes půl Španělska.', 39.4636, -5.8815, 'https://commons.wikimedia.org/wiki/Special:FilePath/Estatua%20de%20Francisco%20Pizarro%20en%20Trujillo.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Estatua%20de%20Francisco%20Pizarro%20en%20Trujillo.JPG"}'::text[], 2),
    (v_route, 'Klášter Guadalupe', 'Královský klášter na seznamu UNESCO, nejvýznamnější mariánské poutní místo Španělska s mudéjarským rajským dvorem. Horská cesta k němu přes pohoří Villuercas je motorkářský bonus.', 39.4527, -5.3273, 'https://commons.wikimedia.org/wiki/Special:FilePath/Real%20Monasterio%20de%20Santa%20Mar%C3%ADa%20de%20Guadalupe%202.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Real%20Monasterio%20de%20Santa%20Mar%C3%ADa%20de%20Guadalupe%202.JPG"}'::text[], 3),
    (v_route, 'Monfragüe – Salto del Gitano', 'Skalní stěna nad soutěskou řeky Tajo, kde krouží desítky supů bělohlavých — jedno z nejlepších pozorování dravců v Evropě, a to přímo od silnice.', 39.8281, -6.0530, 'https://commons.wikimedia.org/wiki/Special:FilePath/Salto%20del%20Gitano,%20Parque%20Nacional%20de%20Monfrag%C3%BCe%20(69623).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Salto%20del%20Gitano,%20Parque%20Nacional%20de%20Monfrag%C3%BCe%20(69623).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Mirador%20del%20Salto%20del%20Gitano%20y%20Rio%20Tajo.jpg"}'::text[], 4),
    (v_route, 'Plasencia', 'Hrazené město se dvěma katedrálami srostlými do jedné a živým náměstím. Příjemná poslední zastávka před návratem do Cáceresu.', 40.0301, -6.0884, 'https://commons.wikimedia.org/wiki/Special:FilePath/Catedral%20de%20Plasencia-1.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Catedral%20de%20Plasencia-1.JPG"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Segovia – Alcázar', 'Hrad na skalní ostruze nad soutokem dvou řek, předloha pohádkových zámků — kamenná loď s modrými věžemi, kde korunovali kastilské krále. Kousek odtud stojí slavný římský akvadukt.', 40.9526, -4.1290, 'https://commons.wikimedia.org/wiki/Special:FilePath/Panor%C3%A1mica%20Oto%C3%B1o%20Alc%C3%A1zar%20de%20Segovia.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Panor%C3%A1mica%20Oto%C3%B1o%20Alc%C3%A1zar%20de%20Segovia.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Alcazar%20de%20Segovia.JPG"}'::text[], 0),
    (v_route, 'Restaurace: Mesón de Cándido (Segovia)', 'Ikonická restaurace pod římským akvaduktem, kde se pečené sele tradičně porcuje talířem. Gastronomická legenda Kastilie s historií sahající do 18. století.', 40.9477, -4.1181, 'https://commons.wikimedia.org/wiki/Special:FilePath/Acueducto%20de%20Segovia%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Acueducto%20de%20Segovia%2001.jpg"}'::text[], 1),
    (v_route, 'Pedraza', 'Dokonale dochovaná středověká vesnice s hradem a arkádovým náměstím, celá z medově zbarveného kamene. Začátkem července ji při slavnosti rozsvěcují tisíce svíček.', 41.1315, -3.8113, 'https://commons.wikimedia.org/wiki/Special:FilePath/Castillo%20de%20Pedraza%201.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Castillo%20de%20Pedraza%201.jpg"}'::text[], 2),
    (v_route, 'Sepúlveda', 'Městečko nad kaňonem řeky Duratón, kde nad červenými střechami krouží supi. Proslulé jehněčím pečeným v hliněných pecích.', 41.2967, -3.7477, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sep%C3%BAlveda,%20Segovia,%20Spain%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sep%C3%BAlveda,%20Segovia,%20Spain%20-%20panoramio.jpg"}'::text[], 3),
    (v_route, 'Hrad Cuéllar', 'Mohutný hrad vévodů z Alburquerque nad městem, které se pyšní nejstaršími běhy býků ve Španělsku. Kombinace gotiky a renesance uprostřed borových lesů.', 41.4019, -4.3175, 'https://commons.wikimedia.org/wiki/Special:FilePath/Castillo%20de%20Cu%C3%A9llar%20(Segovia).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Castillo%20de%20Cu%C3%A9llar%20(Segovia).jpg"}'::text[], 4),
    (v_route, 'Hrad Coca', 'Cihlový mudéjarský hrad, vrchol vojenské architektury 15. století — spíš palác než pevnost. Jeden z nejfotogeničtějších hradů Evropy.', 41.2156, -4.5228, 'https://commons.wikimedia.org/wiki/Special:FilePath/Castillo%20de%20Coca.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Castillo%20de%20Coca.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Castillo%20de%20Coca%20(Segovia).jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Vic – Plaça Major', 'Rozlehlé středověké tržní náměstí lemované podloubím, srdce katalánského vnitrozemí. V úterý a v sobotu tu bývá tradiční trh.', 41.9303, 2.2546, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vic%20(Barcelona).%20Plaza%20Mayor.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vic%20(Barcelona).%20Plaza%20Mayor.jpg"}'::text[], 0),
    (v_route, 'Přehrada Sau', 'Z hladiny přehrady vystupuje věž potopeného románského kostela — čím sušší rok, tím víc staré vesnice vystoupí. Vyhlídky ze silnice nad kaňonem řeky Ter jsou velkolepé.', 41.9709, 2.3990, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tavertet%20-%20Panta%20de%20Sau%20-%20Catalunya%20-%20Spain.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tavertet%20-%20Panta%20de%20Sau%20-%20Catalunya%20-%20Spain.jpg"}'::text[], 1),
    (v_route, 'Rupit', 'Kamenná vesnice přilepená ke skále, do části se vchází po visutém mostě. Jedno z nejromantičtějších míst Katalánska.', 42.0234, 2.4655, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rupit%20i%20Pruit,%20Barcelona,%20Spain%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rupit%20i%20Pruit,%20Barcelona,%20Spain%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Riera%20de%20Rupit,%20a%20su%20paso%20por%20Rupit.jpg"}'::text[], 2),
    (v_route, 'Olot – sopka Montsacopa', 'Město mezi čtyřmi vyhaslými sopkami; na kráter Montsacopa s kostelíkem se dá vyjít přímo z centra. Sopečná krajina Garrotxy čítá přes čtyřicet kuželů.', 42.1876, 2.4899, 'https://commons.wikimedia.org/wiki/Special:FilePath/Volcan%20Montsacopa%20(1).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Volcan%20Montsacopa%20(1).JPG"}'::text[], 3),
    (v_route, 'Restaurace: Cal Sastre (Santa Pau)', 'Rodinný podnik ve středověké Santa Pau proslulý fazolemi fesols de Santa Pau a vulkanickou katalánskou kuchyní. Náměstíčko s podloubím je bonus navrch.', 42.1446, 2.5697, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pla%C3%A7a%20de%20Santa%20Pau,%20la%20Garrotxa,%20Girona.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pla%C3%A7a%20de%20Santa%20Pau,%20la%20Garrotxa,%20Girona.jpg"}'::text[], 4),
    (v_route, 'Castellfollit de la Roca', 'Vesnice natěsnaná na hraně padesátimetrového čedičového srázu nad řekou Fluvià. Nejlepší pohled je z protějšího břehu řeky.', 42.2200, 2.5520, 'https://commons.wikimedia.org/wiki/Special:FilePath/Castellfollit%20de%20la%20Roca%20-%20Vista%20frontal.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Castellfollit%20de%20la%20Roca%20-%20Vista%20frontal.jpg"}'::text[], 5),
    (v_route, 'Besalú – středověký most', 'Opevněný románský most s bránou uprostřed vede do jednoho z nejzachovalejších středověkých městeček Katalánska s židovskou čtvrtí a rituální lázní mikve.', 42.1990, 2.6996, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pont%20Vell%20de%20Besal%C3%BA.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pont%20Vell%20de%20Besal%C3%BA.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Besal%C3%BA%20-%20Pont%20Vell%2010.JPG"}'::text[], 6);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Lanjarón', 'Brána Alpujarras — lázeňské městečko s maurským hradem a pramenitou vodou známou po celém Španělsku. Odtud silnice začíná šplhat do hor.', 36.9190, -3.4770, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20de%20Lanjar%C3%B3n.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20de%20Lanjar%C3%B3n.jpg"}'::text[], 0),
    (v_route, 'Pampaneira', 'První z bílých vesnic v rokli Poqueira — komíny s kloboučky, tkalcovské dílny a uličky, kterými teče voda z hor. Berberská architektura přenesená z afrického Atlasu.', 36.9394, -3.3618, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pampaneira.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pampaneira.jpg"}'::text[], 1),
    (v_route, 'Capileira', 'Nejvýše položená vesnice rokle Poqueira s výhledy na Mulhacén, nejvyšší horu Pyrenejského poloostrova. Bílé terasy domů tu visí nad hlubokým údolím.', 36.9612, -3.3585, 'https://commons.wikimedia.org/wiki/Special:FilePath/Capileira.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Capileira.jpg"}'::text[], 2),
    (v_route, 'Trevélez', 'Nejvýše položená vesnice Španělska (1 486 m) a hlavní město sušené šunky, která tu zraje v čistém horském vzduchu. Serpentiny sem nahoru jsou zážitek samy o sobě.', 37.0007, -3.2654, 'https://commons.wikimedia.org/wiki/Special:FilePath/Trev%C3%A9lez.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Trev%C3%A9lez.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Mesón La Fragua (Trevélez)', 'Horská hospoda s terasou nad střechami Trevélezu — místní šunka, kozí sýr a pstruh ze Sierra Nevady. Poctivá kuchyně po serpentinách chutná dvojnásob.', 37.0010, -3.2650, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20de%20Trev%C3%A9lez.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20de%20Trev%C3%A9lez.jpg"}'::text[], 4),
    (v_route, 'Yegen', 'Vesnice, kterou proslavil britský spisovatel Gerald Brenan knihou Jih od Granady. Východní Alpujarras jsou syrovější a prázdnější — silnice tu bývá jen pro tebe.', 36.9970, -3.0610, 'https://commons.wikimedia.org/wiki/Special:FilePath/Yegen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Yegen.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Cazorla – hrad La Yedra', 'Bílé městečko pod skalami s maurským hradem La Yedra, brána největšího přírodního parku Španělska. Úzké uličky ústí na náměstí s výhledem na hradby.', 37.9105, -3.0037, 'https://commons.wikimedia.org/wiki/Special:FilePath/Castillo%20de%20la%20Yedra.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Castillo%20de%20la%20Yedra.jpg"}'::text[], 0),
    (v_route, 'Restaurace: Mesón Leandro (Cazorla)', 'Rodinný mesón s horskou kuchyní — zvěřina, místní pstruh a segurské olivové oleje. Ideální vydatný start před vjezdem do parku.', 37.9130, -3.0020, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20de%20Cazorla.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20de%20Cazorla.jpg"}'::text[], 1),
    (v_route, 'Río Borosa – Torre del Vinagre', 'Návštěvnické centrum u tyrkysové řeky Borosa, nejslavnější soutěsky parku s dřevěnými lávkami nad vodou. Krátká procházka od parkoviště stojí za protažení nohou.', 38.0110, -2.8940, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rio%20Borosa.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rio%20Borosa.jpg"}'::text[], 2),
    (v_route, 'Embalse del Tranco', 'Dlouhá přehrada na mladém Guadalquiviru — silnice se vine podél břehů desítky kilometrů. Vyhlídky míří na ostrůvek se zříceninou hradu Bujaraiza.', 38.1720, -2.7960, 'https://commons.wikimedia.org/wiki/Special:FilePath/Embalse%20del%20Tranco.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Embalse%20del%20Tranco.jpg"}'::text[], 3),
    (v_route, 'Hornos', 'Vesnička na skalním ostrohu vysoko nad hladinou přehrady, s hradem a planetáriem v jeho věži. Výhled obsáhne celé údolí Guadalquiviru.', 38.2180, -2.7200, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hornos%20de%20Segura.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hornos%20de%20Segura.jpg"}'::text[], 4),
    (v_route, 'Segura de la Sierra', 'Hrad na dokonalém kuželu nad horskou vesnicí, jedno z nejpůsobivějších panoramat Andalusie. Serpentiny nahoru jsou třešnička na konci trasy.', 38.2980, -2.6520, 'https://commons.wikimedia.org/wiki/Special:FilePath/Segura%20de%20la%20Sierra.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Segura%20de%20la%20Sierra.jpg"}'::text[], 5);
