  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Morella', 'Město obehnané dvěma kilometry hradeb s hradem na skále uprostřed — z dálky vypadá jako kamenná koruna. Jedno z nejkrásnějších měst Španělska a domov sýrových koláčků flaons.', 40.6190, -0.1000, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20de%20Morella.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20de%20Morella.jpg"}'::text[], 0),
    (v_route, 'Mirambel', 'Kompletně zachovalé hrazené městečko, kde se od středověku skoro nic nezměnilo. Klenotem je brána Portal de las Monjas se zdobeným mřížovím.', 40.5900, -0.3430, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mirambel.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mirambel.jpg"}'::text[], 1),
    (v_route, 'Cantavieja', 'Hlavní město Maestrazga přilepené na hraně útesu ve 1 300 metrech, s gotickým arkádovým náměstím. Silnice sem nahoru je jedna dlouhá serpentina.', 40.5270, -0.4050, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cantavieja.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cantavieja.jpg"}'::text[], 2),
    (v_route, 'Restaurace: Balfagón (Cantavieja)', 'Horský hotel s kuchyní z místních surovin — jehněčí ternasco, hřiby a lanýže z Maestrazga. Spolehlivá zastávka v kraji, kde je restaurací poskrovnu.', 40.5265, -0.4045, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20de%20Cantavieja.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20de%20Cantavieja.jpg"}'::text[], 3),
    (v_route, 'Órganos de Montoro', 'Stometrové skalní varhany nad silnicí A-1702 — vápencové věže, kde hnízdí supi a po římsách šplhají kozorožci. Nejfotogeničtější úsek celé trasy.', 40.6470, -0.6690, 'https://commons.wikimedia.org/wiki/Special:FilePath/%C3%93rganos%20de%20Montoro.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/%C3%93rganos%20de%20Montoro.jpg"}'::text[], 4),
    (v_route, 'Teruel – mudéjarské věže', 'Nejmenší provinční metropole Španělska s cihlovými věžemi zdobenými keramikou, zapsanými na seznamu UNESCO. Město legendárních milenců z Teruelu a výborné šunky.', 40.3440, -1.1069, 'https://commons.wikimedia.org/wiki/Special:FilePath/Torre%20de%20El%20Salvador%20(Teruel).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Torre%20de%20El%20Salvador%20(Teruel).jpg"}'::text[], 5);
