  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Logroño', 'Metropole Rioji na řece Ebro s katedrálou a kamenným mostem svatojakubské cesty. Startovní i cílový bod vinařského okruhu.', 42.4661, -2.4449, 'https://commons.wikimedia.org/wiki/Special:FilePath/Puente%20de%20Piedra,%20Logro%C3%B1o.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Puente%20de%20Piedra,%20Logro%C3%B1o.jpg"}'::text[], 0),
    (v_route, 'Laguardia', 'Opevněné městečko na kopci uprostřed moře vinic, celé podryté středověkými vinnými sklepy — auta dovnitř nesmí, motorku zaparkuješ před hradbami. Výhled na hřeben Sierra de Cantabria.', 42.5551, -2.5850, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20de%20Laguardia.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vista%20de%20Laguardia.jpg"}'::text[], 1),
    (v_route, 'Haro', 'Vinařské hlavní město Rioji se čtvrtí Barrio de la Estación, kde sídlí nejslavnější vinařství země. Ochutnávku ale nech na dobu, kdy motorka stojí.', 42.5760, -2.8470, 'https://commons.wikimedia.org/wiki/Special:FilePath/Haro,%20La%20Rioja.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Haro,%20La%20Rioja.jpg"}'::text[], 2),
    (v_route, 'Klášter Yuso (San Millán de la Cogolla)', 'Klášter na seznamu UNESCO, kde byly nalezeny první písemné záznamy španělštiny. Tiché údolí San Millán je krásný kontrast k vinicím.', 42.3262, -2.8652, 'https://commons.wikimedia.org/wiki/Special:FilePath/Monasterio%20de%20Yuso.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Monasterio%20de%20Yuso.jpg"}'::text[], 3),
    (v_route, 'Nájera – klášter Santa María la Real', 'Pohřebiště navarrských králů s gotickým klášterem vestavěným do červené skály. Nájera bývala hlavním městem Navarrského království.', 42.4162, -2.7331, 'https://commons.wikimedia.org/wiki/Special:FilePath/Monasterio%20de%20Santa%20Mar%C3%ADa%20la%20Real%20de%20N%C3%A1jera.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Monasterio%20de%20Santa%20Mar%C3%ADa%20la%20Real%20de%20N%C3%A1jera.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Bar Soriano (Logroño)', 'Legenda z Calle del Laurel, nejslavnější tapas uličky Španělska — už přes 80 let tu dělají jedinou věc: žampionové špízy s krevetou. Ideální tečka za okruhem.', 42.4657, -2.4461, 'https://commons.wikimedia.org/wiki/Special:FilePath/Calle%20Laurel,%20Logro%C3%B1o.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Calle%20Laurel,%20Logro%C3%B1o.jpg"}'::text[], 5);
